def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    for c in range(w):
        if any(grid[r][c] == 5 for r in range(h)):
            color = 0
            for r in range(h - 1, -1, -1):
                if grid[r][c] != 0:
                    color = grid[r][c]
                if color:
                    out[r][c] = color
    return out

